from pathlib import Path
p=Path('Studio-Recovery.html')
s=p.read_text(encoding='utf-8')
old='''  #screen-mark .drawing-toolbar{\n    display:grid;\n    grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto auto;\n    grid-template-areas:"customer room zoom zoom" "site site paste choose";\n    overflow:visible;\n  }\n  #screen-mark #drawingCustomerSelect{grid-area:customer;width:100%;min-width:0}\n  #screen-mark #cabinetSelect{grid-area:room;width:100%;min-width:0}\n  #screen-mark #drawingViewSiteMeasurementBtn{grid-area:site;width:100%}\n  #screen-mark #pasteScreenshotBtn{grid-area:paste}\n  #screen-mark #chooseDrawingBtn{grid-area:choose}\n  #screen-mark #deleteDrawingBtn{grid-column:3 / 5;grid-row:3;justify-self:end}\n  #screen-mark .zoom-controls{grid-area:zoom;width:auto;justify-content:flex-end;margin-left:auto}\n  #screen-mark #drawingViewSiteMeasurementBtn[hidden]~#pasteScreenshotBtn{grid-column:1;grid-row:2}\n  #screen-mark #chooseDrawingBtn{min-width:145px}\n  .zoom-value{min-width:42px}\n}'''
new='''  #screen-mark .drawing-toolbar{\n    display:grid;\n    grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto auto;\n    grid-template-areas:"customer room zoom zoom" "paste choose delete .";\n    overflow:visible;\n  }\n  #screen-mark #drawingCustomerSelect{grid-area:customer;width:100%;min-width:0}\n  #screen-mark #cabinetSelect{grid-area:room;width:100%;min-width:0}\n  #screen-mark #drawingViewSiteMeasurementBtn{grid-column:1 / -1;grid-row:3;width:100%}\n  #screen-mark #pasteScreenshotBtn{grid-area:paste}\n  #screen-mark #chooseDrawingBtn{grid-area:choose;min-width:145px}\n  #screen-mark #deleteDrawingBtn{grid-area:delete;justify-self:start;align-self:center;padding:5px 8px;font-size:11px;min-width:0;white-space:nowrap}\n  #screen-mark .zoom-controls{grid-area:zoom;width:auto;justify-content:flex-end;margin-left:auto}\n  .zoom-value{min-width:42px}\n}'''
if s.count(old)!=1: raise SystemExit(f'expected layout block once, found {s.count(old)}')
s=s.replace(old,new,1)
p.write_text(s,encoding='utf-8')
